const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-87.160422, 56.271030]);
  const roi = point.buffer(50000); // 50km buffer for regional analysis

  const date1 = '2020-07-13';
  const date2 = '2020-07-29';

  // 2. Data Acquisition & Check
  // Using Sentinel-1 SAR for sea ice detection
  const col1 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(roi)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'))
    .select('VH');

  const col2 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(roi)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'))
    .select('VH');

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`July 13 Images: ${size1}`);
  console.log(`July 29 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('Missing data for one or both dates');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Create mosaics and detect ice
  const img1 = col1.mosaic();
  const img2 = col2.mosaic();

  // Ice detection: VH backscatter < -20 dB typically indicates ice
  const iceThreshold = -20;
  const ice1 = img1.lt(iceThreshold);
  const ice2 = img2.lt(iceThreshold);

  // 4. Calculate ice area (count ice pixels)
  const stats1 = ice1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = ice2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const count1 = ice1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const icePixels1 = stats1.get('VH').getInfo();
  const icePixels2 = stats2.get('VH').getInfo();
  const totalPixels = count1.get('VH').getInfo();

  console.log(`Total pixels analyzed: ${totalPixels}`);

  if (totalPixels === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Validation & Final Answer
  if (icePixels1 === null || icePixels2 === null || 
      isNaN(icePixels1) || isNaN(icePixels2)) {
    console.log('Calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`July 13 ice pixels: ${icePixels1}`);
  console.log(`July 29 ice pixels: ${icePixels2}`);
  console.log(`Ice coverage July 13: ${(icePixels1/totalPixels*100).toFixed(2)}%`);
  console.log(`Ice coverage July 29: ${(icePixels2/totalPixels*100).toFixed(2)}%`);

  if (icePixels2 > icePixels1) {
    console.log('More ice on July 29 than July 13');
    console.log('<answer>A</answer>');
  } else {
    console.log('Equal or less ice on July 29 than July 13');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
